<template><AdminLayout><div class="container mx-auto px-2 md:px-6 py-6"><div class="mb-6"><h1 class="text-3xl font-medium text-gray-700">Inventario</h1><p class="text-sm text-gray-500">Existencias por almacén · <b>products.stock</b> se mantiene como total temporal de compatibilidad</p></div>
<div class="flex gap-2 mb-4"><button @click="tab='stock'" :class="tab==='stock'?'bg-blue-600 text-white':'bg-white'" class="px-4 py-2 rounded shadow">Existencias</button><button @click="tab='history';loadMovements()" :class="tab==='history'?'bg-blue-600 text-white':'bg-white'" class="px-4 py-2 rounded shadow">Movimientos</button></div>
<div class="bg-white rounded-lg shadow p-4 mb-4 grid md:grid-cols-3 gap-3"><input v-if="tab==='stock'" v-model="search" @input="loadStock" placeholder="Producto o SKU" class="border rounded px-3 py-2"><select v-model="branchId" @change="filtersChanged" class="border rounded px-3 py-2"><option value="">Todas las sedes</option><option v-for="b in branches" :value="b.id">{{b.name}}</option></select><select v-model="warehouseId" @change="filtersChanged" class="border rounded px-3 py-2"><option value="">Todos los almacenes</option><option v-for="w in filteredWarehouses" :value="w.id">{{w.name}}</option></select></div>
<div v-if="tab==='stock'" class="bg-white rounded-lg shadow overflow-x-auto"><table class="min-w-full text-sm"><thead class="bg-gray-100"><tr><th class="p-3 text-left">Producto / SKU</th><th class="p-3 text-left">Sede / almacén</th><th class="p-3">Existencia</th><th class="p-3">Total</th><th class="p-3">Operaciones</th></tr></thead><tbody><tr v-for="x in stock" :key="x.id" class="border-t"><td class="p-3"><b>{{x.product?.name}}</b><div class="font-mono text-xs text-gray-500">{{x.product?.sku}}</div></td><td class="p-3">{{x.warehouse?.branch?.name}}<div class="text-gray-500">{{x.warehouse?.name}}</div></td><td class="p-3 text-center font-bold">{{x.quantity}}</td><td class="p-3 text-center">{{x.product?.total_stock||0}}</td><td class="p-3 text-center whitespace-nowrap"><button @click="openOperation(x,'manual_in')" class="text-green-600 mr-3" title="Entrada"><i class="pi pi-plus-circle"/></button><button @click="openOperation(x,'manual_out')" class="text-red-600 mr-3" title="Salida"><i class="pi pi-minus-circle"/></button><button @click="openOperation(x,'correction')" class="text-orange-600 mr-3" title="Ajuste"><i class="pi pi-pencil"/></button><button @click="openTransfer(x)" class="text-blue-600" title="Traslado"><i class="pi pi-arrow-right-arrow-left"/></button></td></tr><tr v-if="!stock.length"><td colspan="5" class="p-8 text-center text-gray-500">No hay existencias para estos filtros.</td></tr></tbody></table></div>
<div v-else class="bg-white rounded-lg shadow overflow-x-auto"><table class="min-w-full text-sm"><thead class="bg-gray-100"><tr><th class="p-3">Fecha</th><th class="p-3 text-left">Producto</th><th class="p-3 text-left">Ubicación</th><th class="p-3">Tipo</th><th class="p-3">Cantidad</th><th class="p-3">Saldo</th><th class="p-3 text-left">Motivo / usuario</th><th class="p-3">Referencia</th></tr></thead><tbody><tr v-for="m in movements" :key="m.id" class="border-t"><td class="p-3 whitespace-nowrap">{{date(m.created_at)}}</td><td class="p-3"><b>{{m.product?.name}}</b><div class="font-mono text-xs">{{m.product?.sku}}</div></td><td class="p-3">{{m.warehouse?.branch?.name}}<div class="text-gray-500">{{m.warehouse?.name}}</div></td><td class="p-3 text-center"><span class="bg-gray-100 rounded px-2 py-1">{{labels[m.type]||m.type}}</span></td><td :class="incoming.includes(m.type)?'text-green-600':'text-red-600'" class="p-3 text-center font-bold">{{incoming.includes(m.type)?'+':'-'}}{{m.quantity}}</td><td class="p-3 text-center">{{m.quantity_before}} → {{m.quantity_after}}</td><td class="p-3">{{m.reason}}<div class="text-xs text-gray-500">{{m.user?.name||'Sistema'}}</div></td><td class="p-3 text-center text-xs">{{m.reference_type||'—'}} {{m.reference_id||''}}</td></tr></tbody></table><div class="p-3 text-center text-xs text-gray-500">Historial paginado: página {{movementPage.current_page||1}} de {{movementPage.last_page||1}}</div></div>
<div v-if="modal" class="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4"><form @submit.prevent="submit" class="bg-white rounded-lg w-full max-w-lg p-6"><h2 class="text-xl font-bold mb-1">{{operationTitle}}</h2><p class="text-sm text-gray-500 mb-4">{{selected.product?.name}} · Disponible: {{selected.quantity}}</p><label v-if="operation==='transfer'">Destino<select v-model="form.destination_warehouse_id" required class="block w-full border rounded p-2 mt-1 mb-3"><option disabled value="">Seleccione</option><option v-for="w in warehouses.filter(w=>w.id!==selected.warehouse_id&&w.is_active)" :value="w.id">{{w.branch?.name}} · {{w.name}}</option></select></label><label>{{operation==='correction'?'Nuevo saldo físico':'Cantidad'}}<input v-model.number="form.quantity" type="number" :min="operation==='correction'?0:1" required class="block w-full border rounded p-2 mt-1 mb-3"></label><label>Motivo obligatorio<input v-model="form.reason" required maxlength="255" class="block w-full border rounded p-2 mt-1 mb-3"></label><label>Observación<textarea v-model="form.notes" class="block w-full border rounded p-2 mt-1"></textarea></label><div class="flex justify-end gap-3 mt-5"><button type="button" @click="modal=false" class="px-4 py-2 bg-gray-200 rounded">Cancelar</button><button :disabled="saving" class="px-4 py-2 bg-blue-600 text-white rounded">{{saving?'Procesando...':'Confirmar'}}</button></div></form></div>
</div></AdminLayout></template>
<script setup>import AdminLayout from '@/layouts/AdminLayout.vue';import api from '@/api';import{ref,computed,onMounted}from'vue';import{useToast}from'primevue/usetoast';const toast=useToast(),tab=ref('stock'),stock=ref([]),movements=ref([]),movementPage=ref({}),branches=ref([]),warehouses=ref([]),search=ref(''),branchId=ref(''),warehouseId=ref(''),modal=ref(false),saving=ref(false),selected=ref({}),operation=ref(''),form=ref({});let timer;const incoming=['initial','manual_in','transfer_in','cancellation_return'];const labels={initial:'Inicial',manual_in:'Entrada',manual_out:'Salida',transfer_in:'Traslado entrada',transfer_out:'Traslado salida',sale:'Venta',cancellation_return:'Devolución',correction:'Corrección'};
const filteredWarehouses=computed(()=>warehouses.value.filter(w=>!branchId.value||w.branch_id==branchId.value));const operationTitle=computed(()=>({manual_in:'Entrada manual',manual_out:'Salida manual',correction:'Ajuste de inventario',transfer:'Traslado entre almacenes'})[operation.value]);
const params=()=>({search:search.value,branch_id:branchId.value,warehouse_id:warehouseId.value});const loadStock=()=>{clearTimeout(timer);timer=setTimeout(async()=>{try{stock.value=(await api.get('/admin/inventories',{params:params()})).data.data}catch(e){error(e)}},200)};const loadMovements=async()=>{try{const r=(await api.get('/admin/inventory-movements',{params:params()})).data;movements.value=r.data;movementPage.value=r}catch(e){error(e)}};const filtersChanged=()=>{if(warehouseId.value&&!filteredWarehouses.value.some(w=>w.id==warehouseId.value))warehouseId.value='';tab.value==='stock'?loadStock():loadMovements()};
const openOperation=(x,op)=>{selected.value=x;operation.value=op;form.value={quantity:op==='correction'?x.quantity:1,reason:'',notes:''};modal.value=true};const openTransfer=x=>{selected.value=x;operation.value='transfer';form.value={destination_warehouse_id:'',quantity:1,reason:'',notes:''};modal.value=true};
const submit=async()=>{saving.value=true;try{if(operation.value==='transfer')await api.post('/admin/inventories/transfers',{product_id:selected.value.product_id,source_warehouse_id:selected.value.warehouse_id,...form.value});else await api.post('/admin/inventories/adjustments',{product_id:selected.value.product_id,warehouse_id:selected.value.warehouse_id,action:operation.value,...form.value});modal.value=false;toast.add({severity:'success',summary:'Inventario actualizado',life:2500});loadStock()}catch(e){error(e)}finally{saving.value=false}};const error=e=>toast.add({severity:'error',summary:'Operación no completada',detail:e.response?.data?.message||Object.values(e.response?.data?.errors||{})[0]?.[0]||'Error inesperado',life:5000});const date=x=>new Date(x).toLocaleString('es-PE');onMounted(async()=>{try{[branches.value,warehouses.value]=await Promise.all([api.get('/admin/branches').then(r=>r.data.data),api.get('/admin/warehouses').then(r=>r.data.data)])}catch(e){error(e)}loadStock()});</script>
